#!/bin/zsh
TMUX=/opt/homebrew/bin/tmux
[ -x "$TMUX" ] || TMUX=/usr/local/bin/tmux
send() {
  $TMUX send-keys -t $1 C-u; sleep 1
  $TMUX send-keys -t $1 "$2"; sleep 2
  $TMUX send-keys -t $1 Enter; sleep 2
  $TMUX send-keys -t $1 Enter; sleep 1
  echo "sent -> $1"
}
send split-speaker:1.1 "Read and execute /Users/vinaybhardwaj/dev/_fable/orders/split-speaker-roster.md - complete order, and it is the best news of the day. V produced the September OPD schedule at /Users/vinaybhardwaj/Desktop/SEPT 2026 OPD Schedule.xlsx. 19 Sep was a Saturday. Room 3 rosters Dr Animesh 11AM-2PM shared with Dr Rakshitha; Room 5 rosters Dr Prabhudev Salanki 11:30AM-2PM alone. v2's claims ran 11:15-12:36 and v3's ran 11:30:02-13:58 - both inside their rostered slots, v3 starting two seconds after the slot opens, from a document the system has never seen. Turn that into a measurement over all 957 claims with no listening. Hold the line that a roster is a plan and not an attendance record, and tell me plainly if you think the method is weaker than I am presenting it."
send ETA-Refuter:1.1 "NEW TASK, and it is a refutation of MY reasoning, not a diff. I am about to tell V that the September OPD roster independently corroborates the speaker matcher. The claim: on Saturday 19 Sep, room 3 rosters Dr Animesh 11AM-2PM and the matcher's claims for him ran 11:15:53-12:36:43; room 5 rosters Dr Prabhudev Salanki 11:30AM-2PM and the matcher's claims for him ran 11:30:02-13:58:23. I am reading that as independent corroboration because the matcher has never seen the roster. YOUR JOB: try to break that. Specifically - is there ANY path by which room schedule information could already be reaching the matcher or the turn data, directly or indirectly, through room metadata, a visit record, a clinician-room binding, a pinned visit, an encounter, or a seeded clinician list. If such a path exists the corroboration is circular and worthless, and I want to know before V does. Second, quantify the coincidence honestly - given a room where one doctor is rostered most of the working day, how surprising is it really that claims fall inside the slot. If the rostered blocks cover most of the day, agreement is nearly guaranteed and means little; compute what fraction of each room's active hours the slot actually covers. Schedule at /Users/vinaybhardwaj/Desktop/SEPT 2026 OPD Schedule.xlsx. Do not build anything. Verdict plus reasoning, CAP 250 words."
